  booking: { title: 'Booking.com: Understanding your commission', url: 'https://partner.booking.com/en-gb/help/payments-payouts-invoices/invoices/understanding-your-commission', reviewedAt },
  deposits: { title: 'Vrbo: Damage deposit policy', url: 'https://www.vrbo.com/tlp/trust-and-safety/damage-deposit-policy', reviewedAt },
